"""Mine AIDev (v5, AIDev-pop subset) pr_commit_details for agent PR edits to generated files.

Pass 1 (streams every row, incl. patch, with small batches to keep RAM < ~1 GB):
  for every row: path rule (a), lockfile flag, and, if the patch mentions a generated/do-not-edit marker,
  the precise header class (b) from the patch's visible lines 1..15. Writes flagged rows (generated by (a) or by a
  strong/weak header (b), or lockfile) to out/flagged.jsonl.gz (patch kept for generated rows, truncated to 6000 chars).
Pass 2: for PRs with any flagged generated row, collect every changed file in the PR (non-merge commits) to decide
  whether a plausible source changed in the same PR. Writes out/pr_files.json.gz.
Run: venv/bin/python -I build/inthewild/mine.py <aidev_dir> <out_dir>
"""
import gzip, json, os, re, sys, time
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import pyarrow.parquet as pq, pyarrow.compute as pc
from gendetect import path_rule, is_lockfile, header_from_patch

D, OUT = sys.argv[1], sys.argv[2]; os.makedirs(OUT, exist_ok=True)
MERGE = re.compile(r"^Merge (branch|remote-tracking branch|pull request|commit|'|\")")
PREFILTER = r"(?i)(generat|do not edit|do not modify)"
BATCH = 4000
MAXROWS = int(os.environ.get("MAXROWS", "0"))

def open_pf():
    return pq.ParquetFile(os.path.join(D, "pr_commit_details.parquet"), pre_buffer=False, buffer_size=1 << 20)

def pass1():
    pf = open_pf(); t0 = time.time(); n = 0; nflag = 0; stats = {"rows": 0, "merge_rows": 0, "null_patch": 0}
    with gzip.open(os.path.join(OUT, "flagged.jsonl.gz"), "wt") as fo:
        for b in pf.iter_batches(batch_size=BATCH, columns=["sha", "pr_id", "message", "filename", "status", "additions", "deletions", "patch"]):
            pre = pc.fill_null(pc.match_substring_regex(b.column("patch"), PREFILTER), False).to_pylist()
            cols = {k: b.column(k).to_pylist() for k in ("sha", "pr_id", "message", "filename", "status", "additions", "deletions")}
            patches = b.column("patch")
            stats["null_patch"] += patches.null_count
            for i in range(b.num_rows):
                f = cols["filename"][i]
                if f is None: continue
                pr = path_rule(f); lock = is_lockfile(f); hcls, hcov = None, "none"
                p = None
                if pre[i] or pr:
                    p = patches[i].as_py()
                    hcls, hcov = header_from_patch(p, cols["status"][i])
                if not (pr or lock or hcls): continue
                msg = cols["message"][i] or ""
                rec = dict(pr_id=cols["pr_id"][i], sha=cols["sha"][i], merge=bool(MERGE.match(msg)), file=f, status=cols["status"][i],
                           add=cols["additions"][i], dele=cols["deletions"][i], path_rule=pr, lock=lock, hdr=hcls, hdr_cov=hcov,
                           patch_null=not patches[i].is_valid)
                if (pr or hcls) and p: rec["patch"] = p[:6000]
                fo.write(json.dumps(rec) + "\n"); nflag += 1
            n += b.num_rows
            if MAXROWS and n >= MAXROWS: break
            if (n // BATCH) % 250 == 0: print(f"pass1 rows={n} flagged={nflag} t={time.time()-t0:.0f}s", flush=True)
    stats["rows"] = n; stats["flagged"] = nflag; stats["pass1_seconds"] = round(time.time() - t0, 1)
    return stats

def pass2(stats):
    prs = set()
    with gzip.open(os.path.join(OUT, "flagged.jsonl.gz"), "rt") as fi:
        for l in fi:
            r = json.loads(l)
            if (r["path_rule"] or r["hdr"]) and not r["merge"]: prs.add(r["pr_id"])
    pf = open_pf(); files = {}; t0 = time.time(); n = 0; npr_all = set()
    for b in pf.iter_batches(batch_size=50000, columns=["pr_id", "message", "filename", "status"]):
        pid = b.column("pr_id").to_pylist(); fn = b.column("filename").to_pylist(); st = b.column("status").to_pylist(); ms = b.column("message").to_pylist()
        npr_all.update(pid)
        for i in range(b.num_rows):
            if pid[i] in prs and fn[i] is not None and not MERGE.match(ms[i] or ""):
                files.setdefault(pid[i], {})[fn[i]] = st[i]
        n += b.num_rows
        if MAXROWS and n >= MAXROWS: break
    json.dump({str(k): v for k, v in files.items()}, gzip.open(os.path.join(OUT, "pr_files.json.gz"), "wt"))
    json.dump(sorted(npr_all), gzip.open(os.path.join(OUT, "all_pr_ids.json.gz"), "wt"))
    stats.update(prs_with_file_data=len(npr_all), prs_flagged_generated=len(prs), pass2_seconds=round(time.time() - t0, 1))
    return stats

if __name__ == "__main__":
    s = pass1() if "--skip1" not in sys.argv else json.load(open(os.path.join(OUT, "stats.json")))
    json.dump(s, open(os.path.join(OUT, "stats.json"), "w"), indent=1)
    s = pass2(s); json.dump(s, open(os.path.join(OUT, "stats.json"), "w"), indent=1); print(json.dumps(s))
